```js
const desktop = document.getElementById('desktop');
const windowLayer = document.getElementById('windows');
const iconLayer = document.getElementById('icons');
const taskbarButtons = document.getElementById('taskbar-buttons');
const clockEl = document.getElementById('clock');

let nextZ = 10;
const windows = new Map(); // appId -> { app, el, titleEl, button, x, y }

function buildIcons() { for each app id: create button.desktop-icon with svg tile + label; on dblclick -> openApp(id); on click -> select; }

function selectIcon(id) { ...toggle .selected ... }

function openApp(id) {
  const existing = windows.get(id);
  if (existing) { focusWindow(id); return existing; }
  const app = APPS[id];
  const el = document.createElement('div');
  el.className = 'window';
  el.innerHTML = `
    <div class="title-bar">
      <span class="title-icon">${app.iconSvg}</span>
      <span class="title-name">${app.name}</span>
      <button class="win-close" aria-label="Close">✕</button>
    </div>
    <div class="window-content"></div>`;
  // position
  const w = Math.min(app.width, desktop.clientWidth);
  const h = Math.min(app.height, desktop.clientHeight);
  el.style.width = w + 'px';
  el.style.height = h + 'px';
  const cascade = (windows.size % 6) * 28 + 40;
  const x = clamp(cascade, 0, Math.max(0, desktop.clientWidth - w));
  const y = clamp(cascade * 0.75, 0, Math.max(0, desktop.clientHeight - h));
  el.style.left = x + 'px'; el.style.top = y + 'px';
  windowLayer.appendChild(el);
  const content = el.querySelector('.window-content');
  app.createContent(content, id);
  const rec = { app, el, id, width: w, height: h };
  windows.set(id, rec);
  // events
  el.addEventListener('pointerdown', () => focusWindow(id));
  el.querySelector('.win-close').addEventListener('click', (e) => { e.stopPropagation(); closeApp(id); });
  makeTitleBarDraggable(rec);
  // taskbar button
  const btn = document.createElement('button');
  btn.className = 'taskbar-btn';
  btn.textContent = app.name;
  btn.addEventListener('click', () => focusWindow(id));
  taskbarButtons.appendChild(btn);
  rec.button = btn;
  focusWindow(id);
  return rec;
}
```

