Drag implementation:

```js
function makeTitleBarDraggable(rec) {
  const titleBar = rec.el.querySelector('.title-bar');
  titleBar.addEventListener('pointerdown', (e) => {
    if (e.button !== 0) return;
    if (e.target.closest('.win-close')) return;
    e.preventDefault();
    const startX = e.clientX, startY = e.clientY;
    const origX = rec.el.offsetLeft, origY = rec.el.offsetTop;
    titleBar.setPointerCapture(e.pointerId);
    const onMove = (ev) => {
      const maxX = Math.max(0, desktop.clientWidth - rec.width);
      const maxY = Math.max(0, desktop.clientHeight - rec.height);
      const x = clamp(origX + ev.clientX - startX, 0, maxX);
      const y = clamp(origY + ev.clientY - startY, 0, maxY);
      rec.el.style.left = x + 'px';
      rec.el.style.top = y + 'px';
    };
    const onUp = (ev) => {
      titleBar.removeEventListener('pointermove', onMove);
      titleBar.removeEventListener('pointerup', onUp);
      titleBar.removeEventListener('pointercancel', onUp);
    };
    titleBar.addEventListener('pointermove', onMove);
    titleBar.addEventListener('pointerup', onUp);
    titleBar.addEventListener('pointercancel', onUp);
  });
}
```

With pointer capture on the title bar, move/up events go to the title bar. Good.

Note: `rec.width` — the window element's width is set in style; use `rec.el.offsetWidth`. I'll store the size.

focusWindow:

```js
function focusWindow(id) {
  const rec = windows.get(id);
  if (!rec) return;
  rec.el.style.zIndex = String(nextZ++);
  rec.el.classList.add('focused');
  rec.button.classList.add('active');
  for (const [otherId, other] of windows) {
    if (otherId !== id) {
      other.el.classList.remove('focused');
      other.button.classList.remove('active');
    }
  }
}
```

closeApp:

```js
function closeApp(id) {
  const rec = windows.get(id);
  if (!rec) return;
  const wasFocused = rec.el.classList.contains('focused');
  rec.el.remove();
  rec.button.remove();
  windows.delete(id);
  if (wasFocused) {
    // focus the remaining topmost window, if any
    let top = null;
    for (const [otherId, other] of windows) {
      const z = parseInt(other.el.style.zIndex, 10) || 0;
      if (!top || z > parseInt(top.el.style.zIndex,10) || 0) top = other;
    }
    if (top) focusWindow(top.id... );
  }
}
```

