```js
/* ================= Window manager ================= */

const desktop = document.getElementById('desktop');
const windowLayer = document.getElementById('windows');
const iconLayer = document.getElementById('icons');
const taskbarButtons = document.getElementById('taskbar-buttons');
const clockEl = document.getElementById('clock');

/** @type {Map<string, {id, app, el, button, z}>} open windows, keyed by app id */
const openWindows = new Map();
let nextZ = 10;
let selectedIconId = null;

function clamp(v, min, max) { return Math.min(Math.max(v, min), max); }

/* ---------- Desktop icons ---------- */

function buildIcons() {
  for (const id of APP_ORDER) {
    const app = APPS[id];
    const icon = document.createElement('button');
    icon.className = 'desktop-icon';
    icon.id = `icon-${id}`;
    icon.title = app.name + ' (double-click to open)';
    icon.innerHTML =
      `<span class="icon-tile ${app.icon}">${ICON_SVGS[app.icon]}</span>` +
      `<span class="icon-label">${app.name}</span>`;
    icon.addEventListener('click', () => selectIcon(id));
    icon.addEventListener('dblclick', () => openApp(id));
    iconLayer.appendChild(icon);
  }
}

function selectIcon(id) {
  selectedIconId = id;
  for (const other of APP_ORDER) {
    document.getElementById(`icon-${other}`).classList.toggle('selected', other === id);
  }
}

function deselectIcons() {
  selectedIconId = null;
  for (const other of APP_ORDER) {
    document.getElementById(`icon-${other}`).classList.remove('selected');
  }
}

/* ---------- Window creation / closing ---------- */

function openApp(id) {
  if (openWindows.has(id)) { focusWindow(id); return; }   // single instance
  const app = APPS[id];
  const el = document.createElement('div');
  el.className = 'window';
  el.setAttribute('role', 'dialog');
  el.setAttribute('aria-label', app.name);
  el.innerHTML =
    '<div class="title-bar">' +
      `<span class="title-icon">${ICON_SVGS[app.icon]}</span>` +
      `<span class="title-name">${app.name}</span>` +
      '<button class="win-close" aria-label="Close window" title="Close">✕</button>' +
    '</div>' +
    '<div class="window-content"></div>';

  const w = Math.min(app.width, desktop.clientWidth);
  const h = Math.min(app.height, desktop.clientHeight);
  const step = (openWindows.size % 5) * 28;
  const x = clamp(60 + step, 0, Math.max(0, desktop.clientWidth - w));
  const y = clamp(48 + step, 0, Math.max(0, desktop.clientHeight - h));
  el.style.width = w + 'px';
  el.style.height = h + 'px';
  el.style.left = x + 'px';
  el.style.top = y + 'px';
  windowLayer.appendChild(el);

  const rec = { id, app, el, button: null, width: w, height: h };
  el.querySelector('.window-content').appendChild(buildAppContent(id));

  // Focus on any click inside the window.
  el.addEventListener('pointerdown', () => focusWindow(id));
  // Close button.
  el.querySelector('.win-close').addEventListener('click', () => closeApp(id));
  // Dragging.
  enableDragging(rec);

  // Taskbar button (icon + name).
  const button = document.createElement('button');
  button.className = 'taskbar-btn';
  button.innerHTML = `<span class="tb-tile ${app.icon}">${ICON_SVGS[app.icon]}</span><span class="tb-label">${app.name}</span>`;
  button.addEventListener('click', () => focusWindow(id));
  taskbarButtons.appendChild(button);
  rec.button = button;

  openWindows.set(id, rec);
  focusWindow(id);
}

function closeApp(id) {
  const rec = openWindows.get(id);
  if (!rec) return;
  const wasFocused = rec.el.classList.contains('focused');
  rec.el.remove();
  rec.button.remove();
  openWindows.delete(id);
  if (wasFocused) {
    // Hand focus to the remaining topmost window, if any.
    let topId = null;
    let topZ = -1;
    for (const [otherId, other] of openWindows) {
      const z = Number.parseInt(other.el.style.zIndex, 10) || 0;
      if (z > topZ) { topZ = z; topId = otherId; }
    }
    if (topId) focusWindow(topId);
  }
}
```

