  background-color: #e4eaf3;
  background-image:
    linear-gradient(rgba(64, 94, 151, 0.18) 1.5px, transparent 1.5px),
    linear-gradient(90deg, rgba(64, 94, 151, 0.18) 1.5px, transparent 1.5px);
  background-size: var(--wp-size) var(--wp-size);
}

/* 8. Bubbles — offset dot pattern */
.wallpaper-bubbles {
  background-color: #35549c;
  background-image:
    radial-gradient(circle, rgba(255, 255, 255, 0.16) 17%, transparent 18%),
    radial-gradient(circle, rgba(255, 255, 255, 0.08) 17%, transparent 18%);
  background-size:
    var(--wp-size) var(--wp-size),
    calc(var(--wp-size) * 1.5) calc(var(--wp-size) * 1.5);
