content.text:
/* ============================================================
   Browser OS — script.js
   Ticket 2: Wallpaper — right-click context menu on the empty
   desktop, "Change wallpaper" preset picker, localStorage
   persistence. The rest of the shell (windows, apps) belongs
   to the other tickets; this file currently wires up the
   desktop, context menu, picker and taskbar clock.
   ============================================================ */

'use strict';

/* ---------- Wallpaper data (ticket 2) ---------- */
const WALLPAPER_STORAGE_KEY = 'browseros.wallpaper';
const DEFAULT_WALLPAPER = 'aurora';

const WALLPAPERS = [
  { id: 'aurora', name: 'Aurora' },
  { id: 'sunset', name: 'Sunset' },
  { id: 'ocean', name: 'Ocean' },
  { id: 'graphite', name: 'Graphite' },
  { id: 'mist', name: 'Mist' },
  { id: 'dunes', name: 'Dunes' },
  { id: 'grid', name: 'Grid' },
  { id: 'bubbles', name: 'Bubbles' }
];

/* ---------- DOM references ---------- */
const desktopEl = document.getElementById('desktop');
const contextMenuEl = document.getElementById('context-menu');
const pickerEl = document.getElementById('wallpaper-picker');
const pickerGridEl = document.getElementById('picker-grid');
const pickerCloseEl = document.getElementById('picker-close');
const clockEl = document.getElementById('clock');

let currentWallpaper = DEFAULT_WALLPAPER;

/* ---------- Wallpaper (ticket 2) ---------- */
function readStoredWallpaper() {
  try {
    const stored = localStorage.getItem(WALLPAPER_STORAGE_KEY);
    if (stored && WALLPAPERS.some((w) => w.id === stored)) return stored;
  } catch (_) {
    /* storage unavailable (e.g. blocked on file://) — fall back */
  }
  return DEFAULT_WALLPAPER;
}

function applyWallpaper(id) {
  if (!WALLPAPERS.some((w) => w.id === id)) return;
  currentWallpaper = id;

  // Swap the preset class on the desktop.
  WALLPAPERS.forEach((w) => desktopEl.classList.remove('wallpaper-' + w.id));
  desktopEl.classList.add('wallpaper-' + id);

  // Keep the picker's selection ring in sync.
  pickerGridEl.querySelectorAll('.picker-thumb').forEach((btn) => {
    btn.setAttribute('aria-pressed', String(btn.dataset.wallpaper === id));
  });

  try {
    localStorage.setItem(WALLPAPER_STORAGE_KEY, id);
  } catch (_) {
    /* persisting is best-effort */
  }
}

function buildPickerThumbnails() {
  WALLPAPERS.forEach((wp) => {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'picker-thumb';
    btn.dataset.wallpaper = wp.id;
    btn.setAttribute('aria-pressed', 'false');
    btn.title = wp.name;

    const swatch = document.createElement('span');
    swatch.className = 'picker-thumb-swatch wallpaper wallpaper-' + wp.id;
    swatch.setAttribute('aria-hidden', 'true');

    const label = document.createElement('span');
    label.className = 'picker-thumb-name';
    label.textContent = wp.name;

    btn.append(swatch, label);
    btn.addEventListener('click', () => applyWallpaper(wp.id));
    pickerGridEl.appendChild(btn);
  });
}

function openPicker() {
  closeContextMenu();
  pickerEl.hidden = false;
  pickerCloseEl.focus();
}

function closePicker() {
  pickerEl.hidden = true;
}

/* ---------- Context menu (ticket 2) ---------- */
function isDesktopEmptyTarget(target) {
  if (!desktopEl.contains(target)) return false;
  // Over an icon (or a future window) it is not the "empty" desktop.
  return !target.closest('.desktop-icon, .window');
}

function openContextMenu(clientX, clientY) {
  contextMenuEl.hidden = false;

  // Clamp so the menu stays inside the viewport.
  const rect = contextMenuEl.getBoundingClientRect();
  const x = Math.max(8, Math.min(clientX, window.innerWidth - rect.width - 8));
  const y = Math.max(8, Math.min(clientY, window.innerHeight - rect.height - 8));
  contextMenuEl.style.left = x + 'px';
  contextMenuEl.style.top = y + 'px';

  contextMenuEl.querySelector('[data-action="change-wallpaper"]').focus();
}

function closeContextMenu() {
  contextMenuEl.hidden = true;
}

/* ---------- Taskbar clock (shell foundation) ---------- */
function formatClock(date) {
  const h = String(date.getHours()).padStart(2, '0');
  const m = String(date.getMinutes()).padStart(2, '0');
  return h + ':' + m;
}

function updateClock() {
  clockEl.textContent = formatClock(new Date());
}

/* ---------- Event wiring & init ---------- */
function wireEvents() {
  // Right-click on the desktop: suppress the native menu everywhere in
  // the desktop area, open our menu only over the empty part of it.
  desktopEl.addEventListener('contextmenu', (e) => {
    e.preventDefault();
    if (!isDesktopEmptyTarget(e.target)) return;
    openContextMenu(e.clientX, e.clientY);
  });

  // "Change wallpaper" menu item opens the preset picker.
  contextMenuEl.querySelector('[data-action="change-wallpaper"]')
    .addEventListener('click', openPicker);

  // Clicking outside the menu closes it; clicking the backdrop closes
  // the picker.
  document.addEventListener('click', (e) => {
    if (!contextMenuEl.hidden && !contextMenuEl.contains(e.target)) {
      closeContextMenu();
    }
    if (!pickerEl.hidden && e.target === pickerEl) {
      closePicker();
    }
  });

  pickerCloseEl.addEventListener('click', closePicker);

  // Escape closes the picker first, then the context menu.
  document.addEventListener('keydown', (e) => {
    if (e.key !== 'Escape') return;
    if (!pickerEl.hidden) closePicker();
    closeContextMenu();
  });

  // No native context menu on top of the picker overlay.
  pickerEl.addEventListener('contextmenu', (e) => e.preventDefault());
}

function init() {
  buildPickerThumbnails();
  applyWallpaper(readStoredWallpaper());
  wireEvents();
  updateClock();
  setInterval(updateClock, 1000);
}

init();

/* Handle exposed for in-page tests / debugging. */
window.browserOs = {
  getWallpaper: () => currentWallpaper,
  applyWallpaper: applyWallpaper,
  wallpapers: WALLPAPERS,
  storageKey: WALLPAPER_STORAGE_KEY
};

/* ============================================================
   Browser OS — style.css
   Modern flat design (Windows 11 / macOS inspired).
   Ticket 2: wallpaper presets, desktop context menu, picker.
   ============================================================ */

/* ---------- Design tokens ---------- */
:root {
  --accent: #0067c0;
  --taskbar-height: 48px;
  --radius-sm: 8px;
  --radius-md: 10px;
  --radius-lg: 14px;
  --wp-size: 32px; /* base tile size used by pattern wallpapers */
  --font-stack: "Segoe UI Variable", "Segoe UI", system-ui, -apple-system,
    "Helvetica Neue", Arial, sans-serif;
  --shadow-menu: 0 8px 28px rgba(0, 0, 0, 0.28);
  --shadow-panel: 0 16px 48px rgba(0, 0, 0, 0.35);
}

/* ---------- Base ---------- */
* { box-sizing: border-box; }
html, body { height: 100%; }
body {
  margin: 0;
  overflow: hidden;
  font-family: var(--font-stack);
  font-size: 14px;
  color: #1b1c20;
  -webkit-font-smoothing: antialiased;
  user-select: none;
}

/* ---------- Desktop & icons ---------- */
.desktop {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: var(--taskbar-height);
  overflow: hidden;
}

.desktop-icons {
  position: absolute;
  top: 16px;
  left: 16px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.desktop-icon {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  width: 92px;
  padding: 10px 6px;
  border: 1px solid transparent;
  border-radius: var(--radius-md);
  background: transparent;
  font: inherit;
  color: #fff;
  cursor: default;
}

.desktop-icon:hover {
  background: rgba(255, 255, 255, 0.14);
  border-color: rgba(255, 255, 255, 0.22);
}

.desktop-icon .icon {
  font-size: 34px;
  line-height: 1;
  filter: drop-shadow(0 1px 2px rgba(0, 0, 0, 0.35));
}

.desktop-icon .icon-label {
  font-size: 12px;
  font-weight: 500;
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.55);
}

/* ---------- Taskbar & clock ---------- */
.taskbar {
  position: fixed;
  left: 0;
  right: 0;
  bottom: 0;
  height: var(--taskbar-height);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 14px;
  background: rgba(246, 248, 252, 0.72);
  backdrop-filter: blur(18px) saturate(1.4);
  -webkit-backdrop-filter: blur(18px) saturate(1.4);
  border-top: 1px solid rgba(0, 0, 0, 0.08);
  z-index: 9000;
}

.taskbar-buttons {
  display: flex;
  align-items: center;
  gap: 6px;
  min-height: 32px;
}

.clock {
  font-size: 13px;
  font-variant-numeric: tabular-nums;
  color: #2a2c31;
  padding: 4px 10px;
  border-radius: var(--radius-sm);
}

/* ---------- Context menu (ticket 2) ---------- */
.context-menu {
  position: fixed;
  z-index: 9500;
  min-width: 210px;
  padding: 6px;
  background: rgba(249, 249, 251, 0.92);
  backdrop-filter: blur(24px);
  -webkit-backdrop-filter: blur(24px);
  border: 1px solid rgba(0, 0, 0, 0.1);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-menu);
}

.context-menu[hidden] { display: none; }

.context-menu-item {
  display: block;
  width: 100%;
  padding: 8px 12px;
  border: 0;
  border-radius: var(--radius-sm);
  background: transparent;
  font: inherit;
  font-size: 13px;
  text-align: left;
  color: #1b1c20;
  cursor: pointer;
}

.context-menu-item:hover,
.context-menu-item:focus-visible {
  background: rgba(0, 0, 0, 0.07);
  outline: none;
}

/* ---------- Wallpaper presets (ticket 2, CSS only) ----------
   One class per preset; applied to the desktop and to picker
   thumbnails (which shrink --wp-size so patterns scale down). */
.wallpaper {
  background-color: #0f1115;
  background-repeat: repeat;
}

/* 1. Aurora — night sky with a green aurora glow */
.wallpaper-aurora {
  background-image:
    radial-gradient(ellipse 90% 55% at 50% 108%, rgba(52, 211, 153, 0.4), transparent 70%),
    linear-gradient(180deg, #0b1026 0%, #16204a 55%, #1d3557 100%);
}

/* 2. Sunset — dusk fading into a warm horizon */
.wallpaper-sunset {
  background-image: linear-gradient(180deg, #2c1e4f 0%, #7b2d5e 40%, #e8593e 75%, #f9a03f 100%);
}

/* 3. Ocean — deep blue fading to teal */
.wallpaper-ocean {
  background-image: linear-gradient(180deg, #0f3460 0%, #1668a5 55%, #35c4b5 100%);
}

/* 4. Graphite — flat dark solid */
.wallpaper-graphite {
  background-color: #23252c;
}

/* 5. Mist — flat light solid */
.wallpaper-mist {
  background-color: #e9edf3;
}

/* 6. Dunes — warm diagonal stripes */
.wallpaper-dunes {
  background-color: #efe0bd;
  background-image: repeating-linear-gradient(
    45deg,
    rgba(196, 145, 58, 0.25) 0 calc(var(--wp-size) / 2),
    transparent calc(var(--wp-size) / 2) var(--wp-size)
  );
}

/* 7. Grid — subtle graph paper */
.wallpaper-grid {
  background-color: #e4eaf3;
  background-image:
    linear-gradient(rgba(64, 94, 151, 0.18) 1.5px, transparent 1.5px),
    linear-gradient(90deg, rgba(64, 94, 151, 0.18) 1.5px, transparent 1.5px);
  background-size: var(--wp-size) var(--wp-size);
}

/* 8. Bubbles — offset dot pattern */
.wallpaper-bubbles {
  background-color: #35549c;
  background-image:
    radial-gradient(circle, rgba(255, 255, 255, 0.16) 17%, transparent 18%),
    radial-gradient(circle, rgba(255, 255, 255, 0.08) 17%, transparent 18%);
  background-size:
