  document.addEventListener('keydown', (e) => {
    if (e.key !== 'Escape') return;
    if (!pickerEl.hidden) closePicker();
    closeContextMenu();
  });

  // No native context menu on top of the picker overlay.
  pickerEl.addEventListener('contextmenu', (e) => e.preventDefault());
}

